const renderClassyTitle = (text: string) => {
  const normalized = text.toLowerCase().trim();
  if (normalized.includes("testing ai motion graphics agents")) {
    const hasParenthesis = text.includes("(") && text.includes(")");
    let mainPart = "Testing AI motion graphics agents";
    let subPart = "(so you don't have to)";
    
    if (hasParenthesis) {
      const openIdx = text.indexOf("(");
      const closeIdx = text.indexOf(")");
      mainPart = text.substring(0, openIdx).trim();
      subPart = text.substring(openIdx, closeIdx + 1).trim();
    } else {
      mainPart = text;
      subPart = "";
    }
    
    return (
      <div style={{ transition: "none" }}>
        <span>Testing AI </span>
        <span style={{ fontStyle: "italic", fontWeight: "normal" }}>motion graphics</span>
        <span> agents</span>
        {subPart && (
          <div style={{ 
            fontSize: "0.8em", 
            fontStyle: "italic", 
            fontWeight: "normal", 
            marginTop: "6px", 
            opacity: 0.85, 
            color: "#44403c",
            transition: "none"
          }}>
            {subPart}
          </div>
        )}
      </div>
    );
  }
  
  return <div style={{ transition: "none" }}>{text}</div>;
};

